/**
 * Sony Simple IP Protocol (SSIP) module.
 */

function SSIPProtocol(irccip, webapi) {
    this.type;
    this.func;
    this.param;
    this.socket;

    this.irccip = irccip;
    this.webapi = webapi;
};

SSIPProtocol.LF = "\n";
SSIPProtocol.HEADER0 = "*";
SSIPProtocol.HEADER1 = "S";
SSIPProtocol.TYPE_CONTROL = "C";
SSIPProtocol.TYPE_ENQUIRY = "E";
SSIPProtocol.TYPE_ANSWER = "A";
SSIPProtocol.TYPE_NOTIFY = "N";
SSIPProtocol.TIMEOUT = 60000;
SSIPProtocol.MAX_INPUT_PORT = 9999;
SSIPProtocol.MIN_INPUT_PORT = 1;

SSIPProtocol.CMD_LEN = 24;

SSIPProtocol.MASK_POWER   = 0x01;
SSIPProtocol.MASK_CHANNEL = 0x02;
SSIPProtocol.MASK_INPUT   = 0x04;
SSIPProtocol.MASK_MUTE    = 0x08;
SSIPProtocol.MASK_VOLUME  = 0x10;
//SSIPProtocol.MASK_PIP     = 0x20;
SSIPProtocol.MASK_PICMUTE = 0x40;

SSIPProtocol.SUCCESS = '0000000000000000';
SSIPProtocol.ERROR   = 'FFFFFFFFFFFFFFFF';

SSIPProtocol.ON  = '0000000000000001';
SSIPProtocol.OFF = '0000000000000000';

SSIPProtocol.VOID_PARAM = '################';

SSIPProtocol.CHANNEL_NOT_FOUND = 'NNNNNNNNNNNNNNNN';
SSIPProtocol.URI_NOT_FOUND = 'NNNNNNNNNNNNNNNN';
SSIPProtocol.SCENE_NOT_AVAILABLE = 'NNNNNNNNNNNNNNNN';

SSIPProtocol.SUB_SCREEN_POSITION = ['leftTop', 'leftBottom', 'rightTop', 'rightBottom'];

SSIPProtocol.prototype.createAnswer = function(par) {
    return SSIPProtocol.HEADER0 + SSIPProtocol.HEADER1 + SSIPProtocol.TYPE_ANSWER + this.func + par + SSIPProtocol.LF;
};

SSIPProtocol.prototype.createNotify = function(func, par) {
    return SSIPProtocol.HEADER0 + SSIPProtocol.HEADER1 + SSIPProtocol.TYPE_NOTIFY + func + par + SSIPProtocol.LF;
};

SSIPProtocol.prototype.createErrorAnswer = function() {
    return this.createAnswer(SSIPProtocol.ERROR);
};

SSIPProtocol.prototype.createSuccessAnswer = function() {
    return this.createAnswer(SSIPProtocol.SUCCESS);
};

SSIPProtocol.prototype.createOffAnswer = function() {
    return this.createAnswer(SSIPProtocol.OFF);
};

SSIPProtocol.prototype.createOnAnswer = function() {
    return this.createAnswer(SSIPProtocol.ON);
};

SSIPProtocol.prototype.getNumberParameter = function(value) {
    var val = value.toString(10);
    if (val.length > 16) {
        return null;
    }
    val = ('0000000000000000' + val).slice(-16);
    return val;
};

SSIPProtocol.prototype.createNumberAnswer = function(value) {
    var par = this.getNumberParameter(value);
    if (par != undefined && par != null) {
        return this.createAnswer(par);
    } else {
        return this.createErrorAnswer();
    }
};

SSIPProtocol.prototype.getChannelParameter = function(value) {
    var ch = parseFloat(value);
    ch = ch.toString(10);

    var val = ch.split('.');
    var num;
    if (val.length == 2) {
        num = ('00000000' + val[0]).slice(-8) + '.' + (val[1] + '0000000').slice(0, 7);
    } else if (val.length == 1) {
        num = ('00000000' + val[0]).slice(-8) + '.' + '0000000';
    } else {
        num = '';
    }
    return num;
};

SSIPProtocol.prototype.createChannelAnswer = function(value) {
    var par = this.getChannelParameter(value);
    if (par != undefined && par != null && par != '') {
        return this.createAnswer(par);
    } else {
        return this.createErrorAnswer();
    }
};

SSIPProtocol.prototype.getHex16 = function(value) {
    var num = parseInt(value);
    return ('0000' + num.toString(16)).slice(-4);
};

SSIPProtocol.prototype.createTripletAnswer = function(value) {
    var val = value.split('.');
    var num = null;
    if (val.length == 3) {
        num = this.getHex16(val[0]) + this.getHex16(val[1]) + this.getHex16(val[2]) + '####';
    }
    if (num != null) {
        return this.createAnswer(num.toUpperCase());
    } else {
        return this.createErrorAnswer();
    }
};

SSIPProtocol.prototype.createInputStr = function(value) {
    return ('00000000' + value).slice(-8);
};

SSIPProtocol.prototype.getInputSource = function(value) {
    var snum = value.substr(0, 8);
    return parseInt(snum);
};

SSIPProtocol.prototype.getInputPort = function(value) {
    var snum = value.substr(8, 8);
    return parseInt(snum);
};

SSIPProtocol.prototype.createMacAddressAnswer = function(value) {
    var addr = value.replace(/[:]/g, '');
    return this.createAnswer(addr + '####');
};

SSIPProtocol.prototype.createAddressAnswer = function(value) {
    var mask =  (value + '################').substr(0, 16);
    return this.createAnswer(mask);
};

SSIPProtocol.prototype.createInputSourceAnswer = function(value) {
    var mask =  (value + '################').substr(0, 16);
    return this.createAnswer(mask);
};

SSIPProtocol.prototype.createSceneAnswer = function(value) {
    var scene = (value + '################').substr(0, 16);
    return this.createAnswer(scene);
};

// C
SSIPProtocol.prototype.IRCC = function() {
    var self = this;
    if (this.type == SSIPProtocol.TYPE_CONTROL) {
        if (!this.param.match(/^[0-9]{16}$/)) {
            this.socket.write(self.createErrorAnswer());
            return;
        }
        var cmd = parseInt(this.param);
        this.irccip.send(cmd, function(response){
            if (response.match(/<errorCode>/) == null && response.match(/"error"/) == null) {
                self.socket.write(self.createSuccessAnswer());
            } else {
                self.socket.write(self.createErrorAnswer());
                return;
            }
        });
        return;
    } else {
        this.socket.write(this.createErrorAnswer());
        return;
    }
};

// E
SSIPProtocol.prototype.POWR = function() {
    var self = this;
    if (this.type == SSIPProtocol.TYPE_CONTROL) {
        if (!this.param.match(/^[0]{15}[0-1]$/)) {
            this.socket.write(this.createErrorAnswer());
            return;
        }
        var par = parseInt(this.param);
        if (isNaN(par) || !isFinite(par) || (par != 0 && par != 1)) {
            this.socket.write(self.createErrorAnswer());
            return;
        }
        var on = (par == 0) ? false : true;
        var status = null;
        this.webapi.getPowerStatus(function(response) {
            if (response != null && response.error == undefined) {
                status = response.result[0].status;
                self.webapi.setPowerStatus(on, function(response) {
                    if (response != null && response.error == undefined) {
                        self.socket.write(self.createSuccessAnswer());
                    } else {
                        if (on && status == 'active') {
                            self.socket.write(self.createSuccessAnswer());
                        } else {
                            self.socket.write(self.createErrorAnswer());
                        }
                        return;
                    }
                });
            } else {
                self.socket.write(self.createErrorAnswer());
                return;
            }
        });
    } else if (this.type == SSIPProtocol.TYPE_ENQUIRY) {
        if (this.param != SSIPProtocol.VOID_PARAM) {
            this.socket.write(this.createErrorAnswer());
            return;
        }
        this.webapi.getPowerStatus(function(response) {
            if (response != null && response.error == undefined) {
                if (response.result[0].status == 'active') {
                    self.socket.write(self.createOnAnswer());
                } else {
                    self.socket.write(self.createOffAnswer());
                }
            } else {
                self.socket.write(self.createErrorAnswer());
                return;
            }
        });
    } else {
        this.socket.write(this.createErrorAnswer());
        return;
    }
};

// C
SSIPProtocol.prototype.TPOW = function() {
    var self = this;
    var status = null;
    var on = null;
    if (this.type == SSIPProtocol.TYPE_CONTROL) {
        if (this.param != SSIPProtocol.VOID_PARAM) {
            this.socket.write(this.createErrorAnswer());
            return;
        }
        this.webapi.getPowerStatus(function(response) {
            if (response != null && response.error == undefined) {
                status = response.result[0].status;
                if (status == 'active') {
                    on = false;
                } else {
                    on = true;
                }
                self.webapi.setPowerStatus(on, function(response) {
                    if (response != null && response.error == undefined) {
                        self.socket.write(self.createSuccessAnswer());
                    } else {
                        self.socket.write(self.createErrorAnswer());
                        return;
                    }
                });
            } else {
                self.socket.write(self.createErrorAnswer());
                return;
            }
        });
    } else {
        this.socket.write(this.createErrorAnswer());
        return;
    }
};

// C/E
SSIPProtocol.prototype.VOLU = function() {
    var self = this;
    if (this.type == SSIPProtocol.TYPE_CONTROL) {
        if (!this.param.match(/^[0-9]{16}$/)) {
            this.socket.write(this.createErrorAnswer());
            return;
        }
        var vol = parseInt(this.param);
        this.webapi.setAudioVolume(vol, function(response) {
            if (response != null && response.error == undefined) {
                self.socket.write(self.createSuccessAnswer());
            } else {
                self.socket.write(self.createErrorAnswer());
                return;
            }
        });
    } else if (this.type == SSIPProtocol.TYPE_ENQUIRY) {
        if (this.param != SSIPProtocol.VOID_PARAM) {
            this.socket.write(this.createErrorAnswer());
            return;
        }
        this.webapi.getVolumeInformation(function(response) {
            if (response != null && response.error == undefined) {
                var obj = response.result[0];
                for (var i = 0; i < obj.length; i++) {
                    if (obj[i].target == "speaker") {
                        //var vol = (obj[i].volume).toString(10);
                        var vol = obj[i].volume;
                        self.socket.write(self.createNumberAnswer(vol));
                        return;
                    }
                }
            }
            self.socket.write(self.createErrorAnswer());
            return;
        });
    } else {
        this.socket.write(this.createErrorAnswer());
        return;
    }
};

// C/E
SSIPProtocol.prototype.AMUT = function() {
    var self = this;
    if (this.type == SSIPProtocol.TYPE_CONTROL) {
        if (!this.param.match(/^[0]{15}[0-1]$/)) {
            this.socket.write(this.createErrorAnswer());
            return;
        }
        var par = parseInt(this.param);
        if (isNaN(par) || !isFinite(par) || (par != 0 && par != 1)) {
            this.socket.write(this.createErrorAnswer());
            return;
        }
        var on = (par == 0) ? false : true;
        this.webapi.setAudioMute(on, function(response) {
            if (response != null && response.error == undefined) {
                self.socket.write(self.createSuccessAnswer());
            } else {
                self.socket.write(self.createErrorAnswer());
                return;
            }
        });
    } else if (this.type == SSIPProtocol.TYPE_ENQUIRY) {
        if (this.param != SSIPProtocol.VOID_PARAM) {
            this.socket.write(this.createErrorAnswer());
            return;
        }
        this.webapi.getVolumeInformation(function(response) {
            if (response != null && response.error == undefined) {
                var obj = response.result[0];
                for (var i = 0; i < obj.length; i++) {
                    if (obj[i].target == "speaker") {
                        var on = obj[i].mute;
                        if (on) {
                            self.socket.write(self.createOnAnswer());
                        } else {
                            self.socket.write(self.createOffAnswer());
                        }
                        return;
                    }
                }
            }
            self.socket.write(self.createErrorAnswer());
            return;
        });
    } else {
        this.socket.write(this.createErrorAnswer());
        return;
    }
};

// C/E
SSIPProtocol.prototype.CHNN = function() {
    var self = this;

    if (this.type == SSIPProtocol.TYPE_CONTROL) {
        if (!this.param.match(/^[0-9]{8}[.][0-9]{7}$/)) {
            logger.dlog(Logger.VERBOSE, '[CHNN] not match');
            this.socket.write(this.createErrorAnswer());
            return;
        }
        var chNum = parseFloat(this.param);
        if (isNaN(chNum) || !isFinite(chNum)) {
            this.socket.write(self.createErrorAnswer());
            return;
        }
        chNum = chNum.toString(10);

        var source = null;
        var inner = function(recursive) {
            self.webapi.getPlayingContentInfo(function(response) {
                if (response != null && response.error == undefined) {
                    source = response.result[0].source;
                    if (source.match(/^tv:.*$/)){
                        self.webapi.getContentList(source, function(response) {
                            if (response != null && response.error == undefined) {
                                var chlist = response.result[0];
                                for (var j = 0; j < chlist.length; j++) {
                                    // convert '052' -> '52'
                                    var c = parseFloat(chlist[j].dispNum);
                                    if (!isNaN(c) && isFinite(c)) {
                                        var cstr = c.toString(10);
                                        if (cstr == chNum) {
                                            logger.dlog(Logger.VERBOSE, "Channel Found!!");
                                            self.webapi.setPlayContent(encodeURI(chlist[j].uri), function(response) {
                                                if (response != null && response.error == undefined) {
                                                    self.socket.write(self.createSuccessAnswer());
                                                } else {
                                                    self.socket.write(self.createErrorAnswer());
                                                    return;
                                                }
                                            });
                                            return;
                                        }
                                    }
                                }
                                self.socket.write(self.createAnswer(SSIPProtocol.CHANNEL_NOT_FOUND));
                                return;
                            } else {
                                self.socket.write(self.createErrorAnswer());
                                return;
                            }
                        });
                    } else {
                        if (recursive) {
                            self.socket.write(self.createErrorAnswer());
                            return;
                        }
                        self.webapi.setPlayContent("tv:", function(response) {
                            if (response != null && response.error == undefined) {
                                inner(true);
                            } else {
                                self.socket.write(self.createErrorAnswer());
                                return;
                            }
                        });
                    }
                    return;
                } else {
                    self.socket.write(self.createErrorAnswer());
                    return;
                }
            });
        };
        inner(false);

    } else if (this.type == SSIPProtocol.TYPE_ENQUIRY) {
        if (this.param != SSIPProtocol.VOID_PARAM) {
            this.socket.write(this.createErrorAnswer());
            return;
        }
        this.webapi.getPlayingContentInfo(function(response) {
            if (response != null && response.error == undefined) {
                var ch = null;
                if (response.result[0].dispNum == undefined) {
                    self.socket.write(self.createErrorAnswer());
                    return;
                } else {
                    ch = response.result[0].dispNum;
                    self.socket.write(self.createChannelAnswer(ch));
                }
                return;
            } else {
                self.socket.write(self.createErrorAnswer());
                return;
            }
        });
    } else {
        this.socket.write(this.createErrorAnswer());
        return;
    }
};

// C/E
SSIPProtocol.prototype.TCHN = function() {
    var self = this;

    if (this.type == SSIPProtocol.TYPE_CONTROL) {
        if (!this.param.match(/^[0-9A-F]{12}####$/)) {
            this.socket.write(this.createErrorAnswer());
            return;
        }
        var t1 = parseInt(this.param.substr(0, 4), 16);
        var t2 = parseInt(this.param.substr(4, 4), 16);
        var t3 = parseInt(this.param.substr(8, 4), 16);
        var triplet = t1 + '.' + t2 + '.' + t3;
        logger.dlog(Logger.VERBOSE, '[TCHN] >> triplet = ' + triplet);
        var sources = [];
        var uri = {};
        var receive = 0;
        this.webapi.getSourceList(function(response) {
            if (response != null && response.error == undefined) {
                sources = response.result[0];
                for (var i = 0; i < sources.length; i++) {
                    logger.dlog(Logger.VERBOSE, '[CHNN] sources: ' + sources[i].source);
                    self.webapi.getContentList(sources[i].source, function(response) {
                        ++receive;
                        if (response != null && response.error == undefined) {
                            var chlist = response.result[0];
                            for (var j = 0; j < chlist.length; j++) {
                                uri[chlist[j].tripletStr] = chlist[j].uri;
                                logger.dlog(Logger.VERBOSE, '[TCHN] triplet: ' + chlist[j].tripletStr + ' uri: ' + chlist[j].uri);
                            }
                        }

                        if (receive == sources.length) {
                            var u = uri[triplet];
                            if (u != null && u != undefined) {
                                self.webapi.setPlayContent(encodeURI(u), function(response) {
                                    if (response != null && response.error == undefined) {
                                        self.socket.write(self.createSuccessAnswer());
                                    } else {
                                        self.socket.write(self.createErrorAnswer());
                                        return;
                                    }
                                });
                            } else {
                                self.socket.write(self.createAnswer(SSIPProtocol.CHANNEL_NOT_FOUND));
                            }
                        }
                    });
                }
            } else {
                self.socket.write(self.createErrorAnswer());
                return;
            }
        });
    } else if (this.type == SSIPProtocol.TYPE_ENQUIRY) {
        if (this.param != SSIPProtocol.VOID_PARAM) {
            this.socket.write(this.createErrorAnswer());
            return;
        }
        this.webapi.getPlayingContentInfo(function(response) {
            if (response != null && response.error == undefined) {
                var triplet = null;
                if (response.result[0].tripletStr == undefined) {
                    self.socket.write(self.createErrorAnswer());
                    return;
                } else {
                    triplet = response.result[0].tripletStr;
                    self.socket.write(self.createTripletAnswer(triplet));
                }
                return;
            } else {
                self.socket.write(self.createErrorAnswer());
                return;
            }
        });
    } else {
        this.socket.write(this.createErrorAnswer());
        return;
    }
};

// C
SSIPProtocol.prototype.ISRC = function() {
    var self = this;
    if (this.type == SSIPProtocol.TYPE_CONTROL) {
        this.param.match(/^([^#]+)/);
        src = RegExp.$1;
        if (src != null && src != undefined && src != '') {
            self.webapi.getContentList('tv:'+src, function(response) {
                if (response != null && response.error == undefined) {
                    var chlist = response.result[0];
                    if (chlist.length > 0) {
                        self.webapi.setPlayContent(encodeURI(chlist[0].uri), function(response) {
                            if (response != null && response.error == undefined) {
                                self.socket.write(self.createSuccessAnswer());
                            } else {
                                self.socket.write(self.createErrorAnswer());
                                return;
                            }
                        });
                    } else {
                        self.socket.write(self.createAnswer(SSIPProtocol.CHANNEL_NOT_FOUND));
                    }
                } else {
                    self.socket.write(self.createErrorAnswer());
                    return;
                }
            });
        } else {
            this.socket.write(this.createErrorAnswer());
            return;
        }
    } else if (this.type == SSIPProtocol.TYPE_ENQUIRY) {
        if (this.param != SSIPProtocol.VOID_PARAM) {
            this.socket.write(this.createErrorAnswer());
            return;
        }
        this.webapi.getPlayingContentInfo(function(response) {
            if (response != null && response.error == undefined) {
                if (response.result[0].source.match(/^tv:(.*)$/)) {
                    self.socket.write(self.createInputSourceAnswer(RegExp.$1));
                } else {
                    self.socket.write(self.createErrorAnswer());
                }
            } else {
                self.socket.write(self.createErrorAnswer());
                return;
            }
        });

    } else {
        this.socket.write(this.createErrorAnswer());
        return;
    }
};

// C/E
SSIPProtocol.prototype.INPT = function() {
    var self = this;
    if (this.type == SSIPProtocol.TYPE_CONTROL) {
        if (!this.param.match(/^[0]{7}[0-6][0]{4}[0-9]{4}$/)) {
            logger.dlog(Logger.VERBOSE, '[INPT] not match');
            this.socket.write(this.createErrorAnswer());
            return;
        }
        var source = this.getInputSource(this.param);
        var port = this.getInputPort(this.param);
        if (source == 0) {
            if (port != 0) {
                self.socket.write(self.createErrorAnswer());
                return;
            }
        }else {
            if (port < SSIPProtocol.MIN_INPUT_PORT || port > SSIPProtocol.MAX_INPUT_PORT) {
                self.socket.write(self.createErrorAnswer());
                return;
            }
        }

        var uri;
        if (source == 0) {
            uri = 'tv:';
        } else if (source == 1) {
            uri = 'extInput:hdmi?port=' + port;
        } else if (source == 2) {
            uri = 'extInput:scart?port=' + port;
        } else if (source == 3) {
            uri = 'extInput:composite?port=' + port;
        } else if (source == 4) {
            uri = 'extInput:component?port=' + port;
        } else if (source == 5) {
            uri = 'extInput:widi?port=' + port;
        } else if (source == 6) {
            uri = 'extInput:dsub?port=' + port;
        } else {
            this.socket.write(this.createErrorAnswer());
            return;
        }

        this.webapi.setPlayContent(encodeURI(uri), function(response) {
            if (response != null && response.error == undefined) {
                self.socket.write(self.createSuccessAnswer());
            } else {
                if (response.error != undefined) {
                    if (response.error[0] == 3 && response.error[1] == 'invalid uri') {
                        self.socket.write(self.createAnswer(SSIPProtocol.URI_NOT_FOUND));
                    } else {
                        self.socket.write(self.createErrorAnswer());
                        return;
                    }
                } else {
                    self.socket.write(self.createErrorAnswer());
                    return;
                }
            }
        });
    } else if (this.type == SSIPProtocol.TYPE_ENQUIRY) {
        if (this.param != SSIPProtocol.VOID_PARAM) {
            this.socket.write(this.createErrorAnswer());
            return;
        }
        this.webapi.getPlayingContentInfo(function(response) {
            if (response != null && response.error == undefined){
                var u = response.result[0].uri;
                if (u.indexOf('tv:') != -1) {
                    self.socket.write(self.createAnswer('0000000000000000'));
                } else if (u.match(/extInput:([^?]*)[?]port=(.*)/) != null) {
                    var source = RegExp.$1;
                    var port = RegExp.$2;
                    logger.dlog(Logger.VERBOSE, '[INPT] source = ' + source);
                    logger.dlog(Logger.VERBOSE, '[INPT] port   = ' + port);
                    var hiWord;
                    if (source == 'hdmi') {
                        hiWord = self.createInputStr('1');
                    } else if (source == 'scart') {
                        hiWord = self.createInputStr('2');
                    } else if (source == 'composite') {
                        hiWord = self.createInputStr('3');
                    } else if (source == 'component') {
                        hiWord = self.createInputStr('4');
                    } else if (source == 'widi') {
                        hiWord = self.createInputStr('5');
                    } else if (source == 'dsub') {
                        hiWord = self.createInputStr('6');
                    } else {
                        self.socket.write(self.createErrorAnswer());
                        return;
                    }
                    var loWord = self.createInputStr(port);
                    self.socket.write(self.createAnswer(hiWord + loWord));
                } else {
                    self.socket.write(self.createErrorAnswer());
                    return;
                }
            } else {
                self.socket.write(self.createErrorAnswer());
                return;
            }
        });
    } else {
        this.socket.write(this.createErrorAnswer());
        return;
    }
};

// C/E
SSIPProtocol.prototype.PMUT = function() {
    var self = this;
    if (this.type == SSIPProtocol.TYPE_CONTROL) {
        if (!this.param.match(/^[0]{15}[0-1]$/)) {
            this.socket.write(this.createErrorAnswer());
            return;
        }
        var on = parseInt(this.param);
        if (isNaN(on) || !isFinite(on) || (on != 0 && on != 1)) {
            this.socket.write(this.createErrorAnswer());
            return;
        }
        this.webapi.setPowerSavingMode(on, function(response) {
            if (response != null && response.error == undefined) {
                self.socket.write(self.createSuccessAnswer());
            } else {
                self.socket.write(self.createErrorAnswer());
                return;
            }
        });
    } else if (this.type == SSIPProtocol.TYPE_ENQUIRY) {
        if (this.param != SSIPProtocol.VOID_PARAM) {
            this.socket.write(this.createErrorAnswer());
            return;
        }
        this.webapi.getPowerSavingMode(function(response) {
            if (response != null && response.error == undefined) {
                var mode = response.result[0].mode;
                if (mode == null || mode == undefined) {
                    self.socket.write(self.createErrorAnswer());
                    return;
                } else if(mode == 'pictureOff') {
                    self.socket.write(self.createOnAnswer());
                } else {
                    self.socket.write(self.createOffAnswer());
                }
            } else {
                self.socket.write(self.createErrorAnswer());
                return;
            }
        });
    } else {
        this.socket.write(this.createErrorAnswer());
        return;
    }
};

// C
SSIPProtocol.prototype.TPMU = function() {
    var self = this;
    var mode = null;
    var on = null;
    if (this.type == SSIPProtocol.TYPE_CONTROL) {
        if (this.param != SSIPProtocol.VOID_PARAM) {
            this.socket.write(this.createErrorAnswer());
            return;
        }
        this.webapi.getPowerSavingMode(function(response) {
            if (response != null && response.error == undefined) {
                mode = response.result[0].mode;
                if (mode == 'pictureOff') {
                    on = false;
                } else {
                    on = true;
                }
                self.webapi.setPowerSavingMode(on, function(response) {
                    if (response != null && response.error == undefined) {
                        self.socket.write(self.createSuccessAnswer());
                    } else {
                        self.socket.write(self.createErrorAnswer());
                        return;
                    }
                });
            } else {
                self.socket.write(self.createErrorAnswer());
                return;
            }
        });
    } else {
        this.socket.write(this.createErrorAnswer());
        return;
    }
};

