SSIPProtocol.prototype.BADR = function() {
    var self = this;
    var netmask = null;
    var ipaddr = null;
    var bcaddr = [];
    var i = 0;
    if (this.type == SSIPProtocol.TYPE_ENQUIRY) {
        this.param.match(/^([^#]+)/);
        netif = RegExp.$1;
        if (netif != null && netif != undefined && netif != '') {
            this.webapi.getNetworkSettings(netif, function(response) {
                if (response != null && response.error == undefined) {
                    ifs = response.result[0];
                    if (ifs.length > 0) {
                        netmask = (ifs[0].netmask).split(".");
                        ipaddr = (ifs[0].ipAddrV4).split(".");
                        if (netmask.length != 4 || ipaddr.length != 4) {
                            self.socket.write(self.createErrorAnswer());
                            return;
                        }
                        for (i = 0; i < 4; i++) {
                            var mask = parseInt(netmask[i], 10);
                            var addr = parseInt(ipaddr[i], 10);
                            bcaddr[i] = addr | ((~mask) & 0xFF);
                        }
                        self.socket.write(self.createAddressAnswer(bcaddr[0] + '.' + bcaddr[1] + '.' + bcaddr[2] + '.' + bcaddr[3]));
                    } else {
                        self.socket.write(self.createErrorAnswer());
                    }
                } else {
                    self.socket.write(self.createErrorAnswer());
                }
            });
        } else {
            this.socket.write(this.createErrorAnswer());
        }
    } else {
        this.socket.write(this.createErrorAnswer());
    }
};

SSIPProtocol.prototype.MADR = function() {
    var self = this;
    var netif = null;
    var ifs = null;
    if (this.type == SSIPProtocol.TYPE_ENQUIRY) {
        this.param.match(/^([^#]+)/);
        netif = RegExp.$1;
        if (netif != null && netif != undefined && netif != '') {
            this.webapi.getNetworkSettings(netif, function(response) {
                if (response != null && response.error == undefined) {
                    ifs = response.result[0];
                    if (ifs.length > 0) {
                        self.socket.write(self.createMacAddressAnswer(ifs[0].hwAddr));
                    } else {
                        self.socket.write(self.createErrorAnswer());
                    }
                } else {
                    self.socket.write(self.createErrorAnswer());
                }
            });
        } else {
            this.socket.write(this.createErrorAnswer());
        }
    } else {
        this.socket.write(this.createErrorAnswer());
    }
};

SSIPProtocol.prototype.SCEN = function() {
    var self = this;
    if (this.type == SSIPProtocol.TYPE_CONTROL) {
        this.param.match(/^([^#]+)/);
        scene = RegExp.$1;
        if (scene!= null && scene != undefined && scene != '') {
            self.webapi.setSceneSetting(scene, function(response) {
                if (response != null && response.error == undefined) {
                    self.socket.write(self.createSuccessAnswer());
                } else {
                    if (response.error != undefined) {
                        if (response.error[0] == 7 && response.error[1] == 'Illegal State') {
                            self.socket.write(self.createAnswer(SSIPProtocol.SCENE_NOT_AVAILABLE));
                            return;
                        } else {
                            self.socket.write(self.createErrorAnswer());
                            return;
                        }
                    } else {
                        self.socket.write(self.createErrorAnswer());
                        return;
                    }
                }
            });
        } else {
            this.socket.write(this.createErrorAnswer());
            return;
        }
    } else if (this.type == SSIPProtocol.TYPE_ENQUIRY) {
        if (this.param != SSIPProtocol.VOID_PARAM) {
            this.socket.write(this.createErrorAnswer());
            return;
        }
        this.webapi.getSceneSetting(function(response) {
            if (response != null && response.error == undefined) {
                var scene = response.result[0].currentValue;
                self.socket.write(self.createSceneAnswer(scene));
            } else {
                if (response.error != undefined) {
                    if (response.error[0] == 7 && response.error[1] == 'Illegal State') {
                        self.socket.write(self.createAnswer(SSIPProtocol.SCENE_NOT_AVAILABLE));
                        return;
                    } else {
                        self.socket.write(self.createErrorAnswer());
                        return;
                    }
                } else {
                    self.socket.write(self.createErrorAnswer());
                    return;
                }
            }
        });
    } else {
        this.socket.write(this.createErrorAnswer());
    }
};

