SSIPProtocol.prototype.dispatch = function(socket, data) {
    var d = socket['DATA'] + data;

    while(true) {
        if (d.length < SSIPProtocol.CMD_LEN) {
            socket['DATA'] = d;
            break;
        }

        //logger.dlog(Logger.INFO, 'RAW => ' + d);
        var cmd = d.substr(0, SSIPProtocol.CMD_LEN);
        d = d.substr(SSIPProtocol.CMD_LEN, d.length - SSIPProtocol.CMD_LEN);
        //logger.dlog(Logger.INFO, 'REMAINDER => ' + d);
        logger.dlog(Logger.INFO, 'REMAINDER => ' + d.substr(0, 24) + "...");

        if (cmd.charAt(0) != SSIPProtocol.HEADER0
                || cmd.charAt(1) != SSIPProtocol.HEADER1
                || cmd.charAt(23) != SSIPProtocol.LF)
        {
            logger.rlog(Logger.WARN, '<' + cmd + '> is not a valid protocol data!!');
            continue;
        }

        this.type = cmd.charAt(2);
        logger.dlog(Logger.VERBOSE, 'TYPE => ' + this.type);
        this.func = cmd.substr(3, 4);
        logger.dlog(Logger.VERBOSE, 'FUNC => ' + this.func);
        this.param = cmd.substr(7, 16);
        logger.dlog(Logger.VERBOSE, 'PARAM => ' + this.param);
        this.socket = socket;

        if (this.type != 'C' && this.type != 'E' && this.type != 'A') {
            logger.rlog(Logger.WARN, '<' + this.type + '> type is invalid!!');
            continue;
        }

        if (this[this.func] != undefined) {
            this[this.func]();
        } else {
            logger.rlog(Logger.WARN, '<' + this.func + '> function is not found!!');
            continue;
        }
    }
};

SSIPProtocol.prototype.sendNotify = function(socket, status, mask) {
    if (mask & SSIPProtocol.MASK_POWER) {
        if (status.power) {
            socket.write(this.createNotify('POWR', SSIPProtocol.ON));
        } else {
            socket.write(this.createNotify('POWR', SSIPProtocol.OFF));
        }
    } else if (mask & SSIPProtocol.MASK_CHANNEL) {
        var channel = this.getChannelParameter(status.channel);
        socket.write(this.createNotify('CHNN', channel));
    } else if (mask & SSIPProtocol.MASK_INPUT) {
        var hiWord = null;
        var loWord = null;

        if (status.input == 'tv') {
            hiWord = this.createInputStr('0');
            loWord = this.createInputStr('0');
        } else if (status.input == 'hdmi') {
            hiWord = this.createInputStr('1');
        } else if (status.input == 'scart') {
            hiWord = this.createInputStr('2');
        } else if (status.input == 'composite') {
            hiWord = this.createInputStr('3');
        } else if (status.input == 'component') {
            hiWord = this.createInputStr('4');
        } else if (status.input == 'widi') {
            hiWord = this.createInputStr('5');
        } else if (status.input == 'dsub') {
            hiWord = this.createInputStr('6');
        }
        if (loWord == null) {
            loWord = this.createInputStr(status.port);
        }
        if (hiWord != null && loWord != null) {
            socket.write(this.createNotify('INPT', hiWord + loWord));
        }
    } else if (mask & SSIPProtocol.MASK_MUTE) {
        if (status.mute) {
            socket.write(this.createNotify('AMUT', SSIPProtocol.ON));
        } else {
            socket.write(this.createNotify('AMUT', SSIPProtocol.OFF));
        }
    } else if (mask & SSIPProtocol.MASK_VOLUME) {
        var volume = this.getNumberParameter(status.volume);
        socket.write(this.createNotify('VOLU', volume));
    /*
    } else if (mask & SSIPProtocol.MASK_PIP) {
        if (status.pip) {
            socket.write(this.createNotify('PIPI', SSIPProtocol.ON));
        } else {
            socket.write(this.createNotify('PIPI', SSIPProtocol.OFF));
        }
    */
    } else if (mask & SSIPProtocol.MASK_PICMUTE) {
        if (status.picmute) {
            socket.write(this.createNotify('PMUT', SSIPProtocol.ON));
        } else {
            socket.write(this.createNotify('PMUT', SSIPProtocol.OFF));
        }
    }
};

exports.SSIPProtocol = SSIPProtocol;

exports.createSSIPProtocol = function(irccip, webapi) {
    return new SSIPProtocol(irccip, webapi);
};
